import{_ as a,o as t,c as s,a2 as e}from"./chunks/framework.BYgiQ6KE.js";const l="/angular-tutorial-site/assets/EP.17-compiler-ivy.Dm0snMgZ.svg",g=JSON.parse('{"title":"EP.17 模板编译两遍","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.17-compiler-ivy.md","filePath":"comics/EP.17-compiler-ivy.md","lastUpdated":1793863170000}'),o={name:"comics/EP.17-compiler-ivy.md"};function d(n,i,r,h,c,p){return t(),s("div",null,[...i[0]||(i[0]=[e('<h1 id="ep-17-模板编译两遍" tabindex="-1">EP.17 模板编译两遍 <a class="header-anchor" href="#ep-17-模板编译两遍" aria-label="Permalink to &quot;EP.17 模板编译两遍&quot;">​</a></h1><p><img src="'+l+`" alt="EP.17 模板编译两遍"></p><blockquote><p>对应正文：<a href="./../guide/part7/17-compiler-ivy">17-compiler-ivy</a>（1 编译流程 / 3 TCB / 4 运行时表示 / 6 signal 依赖图 / 8 常见坑）· 配套示例：<code>hello-binding</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君发现模板里属性拼错也要等构建才报，<code>@for</code> 不写 <code>track</code> 直接编译失败；Angular 到底是不是虚拟 DOM？</li><li><strong>第 2 格</strong>：码叔拆出编译四步——<code>parse</code> 生成 AST、<code>bind</code> 建立语义、TCB 做模板类型检查、<code>emit</code> 生成 <code>ɵɵelementStart</code> 指令。</li><li><strong>第 3 格</strong>：像素酱看到运行时没有虚拟 DOM 树，只有指令与 <code>LView</code>；signal 依赖图按需计算，读取时才求值并缓存。</li><li><strong>第 4 格</strong>：码叔结案——<strong>编译期越严格，运行时越轻</strong>；模板类型、依赖追踪都被前移。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-模板错误为什么提前" tabindex="-1">第 1 格 · 模板错误为什么提前 <a class="header-anchor" href="#第-1-格-·-模板错误为什么提前" aria-label="Permalink to &quot;第 1 格 · 模板错误为什么提前&quot;">​</a></h3><p>Ivy 在构建期就把模板编译成指令。<code>@for</code> 必须提供 <code>track</code> 以声明身份；属性拼写由模板类型检查（TCB）发现：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@for (item of items; track item.id) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> [title]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;item.name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{{ item.name }}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>track</code> 不是语法糖，它决定了复用与更新的身份键。</p><h3 id="第-2-格-·-编译四步" tabindex="-1">第 2 格 · 编译四步 <a class="header-anchor" href="#第-2-格-·-编译四步" aria-label="Permalink to &quot;第 2 格 · 编译四步&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>输入</th><th>输出</th></tr></thead><tbody><tr><td><code>parse</code></td><td>HTML + 绑定语法</td><td>AST</td></tr><tr><td><code>bind</code></td><td>AST</td><td>语义节点与依赖</td></tr><tr><td>TCB</td><td>组件上下文类型</td><td>模板类型错误</td></tr><tr><td><code>emit</code></td><td>语义节点</td><td>指令函数</td></tr></tbody></table><p>生成的组件定义（<code>ComponentDef</code>）包含选择器、输入输出、指令与模板函数。</p><h3 id="第-3-格-·-运行时表示" tabindex="-1">第 3 格 · 运行时表示 <a class="header-anchor" href="#第-3-格-·-运行时表示" aria-label="Permalink to &quot;第 3 格 · 运行时表示&quot;">​</a></h3><p>浏览器端没有「虚拟 DOM 树」，而是：</p><ul><li>每个组件实例对应一个 <code>LView</code>，保存绑定值与子节点；</li><li>模板函数按顺序调用 <code>ɵɵelementStart</code> / <code>ɵɵtext</code> / <code>ɵɵelementEnd</code>；</li><li>变更检测通过标记与刷新，不是全树 diff。</li></ul><p>signal 则更进一步：producer 变化只标记消费者，读取时才求值，结果自动缓存。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> price</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> signal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> total</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> computed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> price</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 读取时才计算并缓存</span></span></code></pre></div><h3 id="第-4-格-·-为什么不用虚拟-dom" tabindex="-1">第 4 格 · 为什么不用虚拟 DOM <a class="header-anchor" href="#第-4-格-·-为什么不用虚拟-dom" aria-label="Permalink to &quot;第 4 格 · 为什么不用虚拟 DOM&quot;">​</a></h3><p>虚拟 DOM 的成本是「每次更新都创建新树 + diff」。Ivy 选择了「编译期生成更新指令 + 运行时按依赖标记」，把结构信息前移，减少运行时分配。</p><p>代价是模板必须能被静态分析：动态拼接模板、<code>any</code> 绕过类型、在模板里做重计算，都会削弱这些优势。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../guide/part7/17-compiler-ivy#8-常见坑">常见坑表格</a></p></blockquote><ol><li><code>@for</code> 不写 <code>track</code> → <strong>编译期直接报错，身份键缺失</strong>；</li><li>用 <code>any</code> 绕开模板类型 → <strong>TCB 形同虚设，错误推迟到运行期</strong>；</li><li>在模板里做重计算 → <strong>每次变更都重跑，移到 <code>computed</code> 或组件方法</strong>；</li><li>把 signal 当普通变量 → <strong>丢失依赖追踪，更新不触发</strong>；</li><li>依赖实现细节（<code>ɵɵ</code> 前缀）→ <strong>属于私有 API，升级即破坏</strong>。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>Angular 为什么不需要虚拟 DOM？——<strong>Ivy 在编译期把模板转成更新指令，运行时通过 <code>LView</code> 与依赖标记直接更新真实 DOM，避免每次创建新树并 diff 的成本</strong>。</li><li><code>track</code> 的作用是什么？——<strong>为 <code>@for</code> 提供身份键，决定列表项复用与更新的依据；缺失时编译失败，错误复用会导致状态错位</strong>。</li><li>TCB 检查了什么？——<strong>模板中表达式与指令的上下文类型，包括属性名、输入输出类型、可用的组件成员；它把模板错误提前到构建期</strong>。</li></ol>`,26)])])}const E=a(o,[["render",d]]);export{g as __pageData,E as default};
